     7.3.0
     यो function अब केवल एउटा parameter सहित call गर्न सकिन्छ। पहिले, कम्तीमा दुईवटा parameters आवश्यक पर्थ्यो।

  &reftitle.examples;



    array_push को उदाहरण


<?php
$stack = array("orange", "banana");
array_push($stack, "apple", "raspberry");
print_r($stack);
?>


    &example.outputs;


Array
(
    [0] => orange
    [1] => banana
    [2] => apple
    [3] => raspberry
)
